1	'use client';
2	
3	import {
4	    Anchor,
5	    Button,
6	    Checkbox,
7	    Container,
8	    Group,
9	    Paper,
10	    Stack,
11	    Table,
12	    TableCaption,
13	    TableTbody,
14	    TableTd,
15	    TableTh,
16	    TableThead,
17	    TableTr,
18	    Text,
19	    TextInput,
20	    UnstyledButton,
21	} from '@mantine/core';
22	import { notifications } from '@mantine/notifications';
23	import { IconChevronDown, IconChevronUp, IconSelector } from '@tabler/icons-react';
24	import { useRouter } from 'next/navigation';
25	import { useMemo, useState } from 'react';
26	
27	import {
28	    buildInviteEmail,
29	    comparePlayers,
30	    getImpersonationLabel,
31	    getPreferredEmail,
32	    isOnboarded,
33	    type SortDirection,
34	    type SortKey,
35	} from '@/lib/adminPlayer';
36	import { config } from '@/lib/config';
37	import { formatDate } from '@/lib/dates';
38	import { normalizeEmail } from '@/lib/email/normalizeEmail';
39	import { assertOkResponse, toPublicMessage } from '@/lib/errors';
40	import { captureUnexpectedError } from '@/lib/observability/sentry';
41	import { PlayerDataType } from '@/types';
42	import { AddPlayerInviteProxy } from '@/types/actions/CreatePlayer';
43	import type { SendEmailProxy } from '@/types/actions/SendEmail';
44	
45	export interface Props {
46	    players: PlayerDataType[];
47	    userEmails?: string[];
48	    userIdByEmail?: Record<string, string>;
49	    onAddPlayerInvite: AddPlayerInviteProxy;
50	    onSendEmail: SendEmailProxy;
51	}
52	
53	/**
54	 * Admin table for managing players, invitations, and email verification.
55	 *
56	 * @param props - Component props.
57	 * @param props.players - Players to render in the table.
58	 * @param props.userEmails - Better Auth user emails to determine onboarding status.
59	 * @returns The rendered admin player list table.
60	 */
61	export const AdminPlayerList = ({
62	    players,
63	    userEmails,
64	    userIdByEmail,
65	    onAddPlayerInvite,
66	    onSendEmail,
67	}: Props) => {
68	    const router = useRouter();
69	    const userEmailSet = useMemo(
70	        () => new Set((userEmails ?? [])
71	            .map((email) => normalizeEmail(email)).filter((email) => email.length > 0)),
72	        [userEmails],
73	    );
74	    const [sortKey, setSortKey] = useState<SortKey>('id');
75	    const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
76	    const [selectedIds, setSelectedIds] = useState<number[]>([]);
77	    const [filter, setFilter] = useState('');
78	
79	    /**
80	     * Filters players by name based on the current text input.
81	     *
82	     * @returns The filtered player list.
83	     */
84	    const filteredPlayers = useMemo(() => {
85	        if (!players) return [];
86	        const trimmedFilter = filter.trim().toLowerCase();
87	        if (!trimmedFilter) return players;
88	        return players.filter((player) => (
89	            player.name?.toLowerCase().includes(trimmedFilter)
90	        ));
91	    }, [players, filter]);
92	
93	    /**
94	     * Applies sorting to the filtered players.
95	     *
96	     * @returns The sorted player list.
97	     */
98	    const sortedPlayers = useMemo(() => {
99	        const data = [...filteredPlayers];
100	        data.sort((a, b) => comparePlayers(a, b, sortKey, sortDirection, userEmailSet));
101	        return data;
102	    }, [filteredPlayers, sortKey, sortDirection, userEmailSet]);
103	
104	    if (!players) {
105	        return (
106	            <Text>Loading players...</Text>
107	        );
108	    }
109	
110	    if (players.length === 0) {
111	        return (
112	            <Text>No players found.</Text>
113	        );
114	    }
115	
116	    /**
117	     * Selects or clears all visible players.
118	     *
119	     * @param checked - Whether the select-all checkbox is checked.
120	     */
121	    const toggleSelectAll = (checked: boolean) => {
122	        setSelectedIds(checked ? filteredPlayers.map((player) => player.id) : []);
123	    };
124	
125	    /**
126	     * Toggles a single player row selection.
127	     *
128	     * @param playerId - The player ID to toggle.
129	     * @param checked - Whether the checkbox is checked.
130	     */
131	    const toggleSelectPlayer = (playerId: number, checked: boolean) => {
132	        setSelectedIds((prev) => (
133	            checked ?
134	                [...prev, playerId] :
135	                prev.filter((id) => id !== playerId)
136	        ));
137	    };
138	
139	    const allSelected = filteredPlayers.length > 0 && selectedIds.length === filteredPlayers.length;
140	    const someSelected = selectedIds.length > 0 && !allSelected;
141	    const hasSelection = selectedIds.length > 0;
142	    const selectedPlayers = players.filter((player) => selectedIds.includes(player.id));
143	
144	    /**
145	     * Returns the sort icon for the provided column key.
146	     *
147	     * @param key - Column sort key.
148	     * @returns The appropriate sort icon element.
149	     */
150	    const getSortIcon = (key: SortKey) => {
151	        if (key !== sortKey) return <IconSelector size={14} />;
152	        return sortDirection === 'asc' ? <IconChevronUp size={14} /> : <IconChevronDown size={14} />;
153	    };
154	
155	    /**
156	     * Renders a sortable header label with the current sort icon.
157	     *
158	     * @param label - Column display label.
159	     * @param key - Column sort key.
160	     * @returns A sortable header element.
161	     */
162	    const renderSortHeader = (label: string, key: SortKey) => (
163	        <UnstyledButton
164	            type="button"
165	            onClick={() => handleSort(key)}
166	            aria-label={`Sort by ${label}`}
167	        >
168	            <Group gap={6} wrap="nowrap">
169	                <Text span>{label}</Text>
170	                {getSortIcon(key)}
171	            </Group>
172	        </UnstyledButton>
173	    );
174	
175	    /**
176	     * Updates the sort state for the selected column.
177	     *
178	     * @param key - Column sort key.
179	     */
180	    const handleSort = (key: SortKey) => {
181	        if (key === sortKey) {
182	            setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
183	            return;
184	        }
185	        setSortKey(key);
186	        setSortDirection('asc');
187	    };
188	
189	    /**
190	     * Sends onboarding invites and extra email verifications for the selected
191	     * players. Not expected to called with an empty list since the button is
192	     * disabled, but will handle that case anyway.
193	     *
194	     * @param onboardPlayers - The players to onboard.
195	     * @returns A promise that resolves when onboarding emails are handled.
196	     */
197	    const handleOnboardPlayers = async (onboardPlayers: PlayerDataType[]) => {
198	        const id = notifications.show({
199	            loading: true,
200	            title: 'Onboarding players',
201	            message: 'Sending onboarding emails...',
202	            autoClose: false,
203	            withCloseButton: false,
204	        });
205	
206	        try {
207	            let inviteSent = 0;
208	            let inviteSkipped = 0;
209	            for (const player of onboardPlayers) {
210	                const email = getPreferredEmail(player);
211	                if (!email) {
212	                    inviteSkipped += 1;
213	                } else {
214	                    const inviteLink = await onAddPlayerInvite(player.id, email);
215	                    const html = buildInviteEmail(inviteLink);
216	                    const cc = 'footy@toastboy.co.uk';
217	                    await onSendEmail({
218	                        to: email,
219	                        cc,
220	                        subject: 'Welcome to Toastboy FC!',
221	                        html,
222	                    });
223	                    inviteSent += 1;
224	                }
225	            }
226	
227	            notifications.update({
228	                id,
229	                color: 'teal',
230	                title: 'Onboarding sent',
231	                message: [
232	                    `Invites: ${inviteSent} sent`,
233	                    inviteSkipped ? `${inviteSkipped} skipped` : null,
234	                ].filter(Boolean).join('. ') + '.',
235	                loading: false,
236	                autoClose: config.notificationAutoClose,
237	            });
238	        } catch (err) {
239	            captureUnexpectedError(err, {
240	                layer: 'client',
241	                component: 'AdminPlayerList',
242	                action: 'sendOnboarding',
243	                route: '/footy/admin/players',
244	                extra: {
245	                    selectedCount: selectedIds.length,
246	                },
247	            });
248	            notifications.update({
249	                id,
250	                color: 'red',
251	                title: 'Error',
252	                message: toPublicMessage(err, 'Failed to onboard players.'),
253	                loading: false,
254	                autoClose: false,
255	                withCloseButton: true,
256	            });
257	        }
258	    };
259	
260	    const getUserIdForPlayer = (player: PlayerDataType) => {
261	        const email = normalizeEmail(player.accountEmail);
262	        if (!email) return null;
263	        return userIdByEmail?.[email] ?? null;
264	    };
265	
266	    const handleImpersonatePlayer = async (player: PlayerDataType) => {
267	        const userId = getUserIdForPlayer(player);
268	
269	        // The button should be disabled if there's no userId.
270	
271	        const id = notifications.show({
272	            loading: true,
273	            title: 'Starting impersonation',
274	            message: 'Switching session...',
275	            autoClose: false,
276	            withCloseButton: false,
277	        });
278	
279	        try {
280	            const response = await fetch('/api/auth/admin/impersonate-user', {
281	                method: 'POST',
282	                headers: { 'Content-Type': 'application/json' },
283	                body: JSON.stringify({ userId }),
284	            });
285	
286	            await assertOkResponse(response, {
287	                method: 'POST',
288	                fallbackMessage: 'Failed to impersonate user.',
289	            });
290	
291	            router.refresh();
292	            notifications.update({
293	                id,
294	                color: 'teal',
295	                title: 'Impersonation active',
296	                message: `Now impersonating ${getImpersonationLabel(player)}.`,
297	                loading: false,
298	                autoClose: config.notificationAutoClose,
299	            });
300	        } catch (err) {
301	            const message = toPublicMessage(err, 'Failed to impersonate user.');
302	            notifications.update({
303	                id,
304	                color: 'red',
305	                title: 'Error',
306	                message,
307	                loading: false,
308	                autoClose: false,
309	                withCloseButton: true,
310	            });
311	        }
312	    };
313	
314	    const rows = sortedPlayers.map((player: PlayerDataType) => {
315	        const playerHref = `/footy/player/${encodeURIComponent(player.id || '')}`;
316	        const hasAuthAccount = isOnboarded(player, userEmailSet);
317	        const hasExtraEmails = player.extraEmails.length > 0;
318	        const extraEmailsVerified = hasExtraEmails && player.extraEmails.every((email) => email.verified);
319	        const userId = getUserIdForPlayer(player);
320	
321	        return (
322	            <TableTr key={player.id}>
323	                <TableTd w="2.5rem">
324	                    <Checkbox
325	                        checked={selectedIds.includes(player.id)}
326	                        onChange={(event) => toggleSelectPlayer(player.id, event.currentTarget.checked)}
327	                        aria-label={`Select ${player.name ?? ''}`}
328	                    />
329	                </TableTd>
330	                <TableTd w="4rem">
331	                    <Anchor href={playerHref}>{player.id}</Anchor>
332	                </TableTd>
333	                <TableTd>
334	                    <Anchor href={playerHref}>{player.name}</Anchor>
335	                </TableTd>
336	                <TableTd>{formatDate(player.joined)}</TableTd>
337	                <TableTd>{formatDate(player.finished)}</TableTd>
338	                <TableTd>{hasAuthAccount ? 'Yes' : 'No'}</TableTd>
339	                <TableTd>{hasExtraEmails ? (extraEmailsVerified ? 'Yes' : 'No') : ''}</TableTd>
340	                <TableTd>
341	                    <Button
342	                        size="xs"
343	                        variant="light"
344	                        disabled={!userId}
345	                        onClick={() => handleImpersonatePlayer(player)}
346	                    >
347	                        Impersonate
348	                    </Button>
349	                </TableTd>
350	            </TableTr>
351	        );
352	    });
353	
354	    return (
355	        <Container fluid>
356	            <Paper w="100%" p="xl">
357	                <Stack gap="sm">
358	                    <Text fw={700}>
359	                        Players ({players.length})
360	                    </Text>
361	                    <Group justify="space-between" align="center" wrap="wrap">
362	                        <TextInput
363	                            placeholder="Filter by name"
364	                            value={filter}
365	                            onChange={(event) => setFilter(event.currentTarget.value)}
366	                        />
367	                        <Group gap="xs">
368	                            <Button
369	                                size="xs"
370	                                type="button"
371	                                disabled={!hasSelection}
372	                                onClick={() => handleOnboardPlayers(selectedPlayers)}
373	                            >
374	                                Onboard player
375	                            </Button>
376	                        </Group>
377	                    </Group>
378	                    <Table
379	                        striped
380	                        highlightOnHover
381	                        withTableBorder
382	                        withColumnBorders
383	                        w="100%"
384	                        style={{ tableLayout: 'fixed' }}
385	                    >
386	                        <TableCaption>Registered players</TableCaption>
387	                        <TableThead>
388	                            <TableTr>
389	                                <TableTh w="2.5rem">
390	                                    <Checkbox
391	                                        checked={allSelected}
392	                                        indeterminate={someSelected}
393	                                        onChange={(event) => toggleSelectAll(event.currentTarget.checked)}
394	                                        aria-label="Select all players"
395	                                    />
396	                                </TableTh>
397	                                <TableTh
398	                                    w="4rem"
399	                                    aria-sort={sortKey === 'id' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}
400	                                >
401	                                    {renderSortHeader('ID', 'id')}
402	                                </TableTh>
403	                                <TableTh aria-sort={sortKey === 'name' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
404	                                    {renderSortHeader('Name', 'name')}
405	                                </TableTh>
406	                                <TableTh aria-sort={sortKey === 'joined' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
407	                                    {renderSortHeader('Joined', 'joined')}
408	                                </TableTh>
409	                                <TableTh aria-sort={sortKey === 'finished' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
410	                                    {renderSortHeader('Finished', 'finished')}
411	                                </TableTh>
412	                                <TableTh aria-sort={sortKey === 'auth' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
413	                                    {renderSortHeader('Auth', 'auth')}
414	                                </TableTh>
415	                                <TableTh aria-sort={sortKey === 'extraEmails' ? (sortDirection === 'asc' ? 'ascending' : 'descending') : 'none'}>
416	                                    {renderSortHeader('Emails Verified', 'extraEmails')}
417	                                </TableTh>
418	                                <TableTh w="7rem">Impersonate</TableTh>
419	                            </TableTr>
420	                        </TableThead>
421	                        <TableTbody>{rows}</TableTbody>
422	                    </Table>
423	                </Stack>
424	            </Paper>
425	        </Container>
426	    );
427	};
