const [sortKey, setSortKey] = useState<SortKey>('id');
const [sortDirection, setSortDirection] = useState<SortDirection>('asc');
const [selectedIds, setSelectedIds] = useState<number[]>([]);
const [filter, setFilter] = useState('');
const [filterFinished, setFilterFinished] = useState(false);
const [filterAuth, setFilterAuth] = useState(false);
const [filterEmailsVerified, setFilterEmailsVerified] = useState(false);

/**
 * Filters players by name and the active checkbox filters.
 *
 * @returns The filtered player list.
 */
const filteredPlayers = useMemo(() => {
    if (!players) return [];
    const trimmedFilter = filter.trim().toLowerCase();
    return players.filter((player) => {
        if (trimmedFilter && !player.name?.toLowerCase().includes(trimmedFilter)) return false;
        if (filterFinished && !player.finished) return false;
        if (filterAuth && !isOnboarded(player, userEmailSet)) return false;
        if (filterEmailsVerified) {
            const hasExtraEmails = player.extraEmails.length > 0;
            const extraEmailsVerified = hasExtraEmails && player.extraEmails.every((email) => email.verified);
            if (!extraEmailsVerified) return false;
        }
        return true;
    });
}, [players, filter, filterFinished, filterAuth, filterEmailsVerified, userEmailSet]);

