        expect(screen.getByText('Anonymous')).toBeInTheDocument();
        expect(screen.queryByText('Authed')).not.toBeInTheDocument();
    });

    it('filters to only players with verified emails when Verified is selected', () => {
        const players = [
            createMockPlayerData({
                id: 1,
